// priority: -21
// Addon food mods added by Sunlit Valley (not in the original pack). Generated by gen_prices.py; raw ingredient sums, station multiplier applied on push.
// Runs after globalRegistry.js (priority -20) so global.cooking, global.crops and friends already exist.

// Addon food mods added by Sunlit Valley (not in the original pack)
// brewingStationRecipes is pushed into global.cooking, not global.brews: the registry brews->aged/trades loops already ran before this file, so global.brews would only create broken aged_ entries.
// IMPORTANT: because those trades loops already ran, every entry pushed here must also
// register its own trade. Otherwise the shipping bin tooltip shows a price (the lists are
// read by addPriceTooltips.js) but the bin refuses the item, because isSellable only checks
// global.trades (see globalShippingBinHandlers.js).
const addAddonFood = (list, item, value, attribute) => {
  list.push({ item: item, value: value });
  if (global.trades.has(item)) return;
  global.trades.set(item, {
    value: global.getConfiguredValue(value, attribute),
    multiplier:
      attribute === "wood"
        ? "shippingbin:wood_sell_multiplier"
        : attribute === "meat"
        ? "shippingbin:meat_sell_multiplier"
        : attribute === "gem"
        ? "shippingbin:gem_sell_multiplier"
        : "shippingbin:crop_sell_multiplier",
  });
};
